effect.shader:
const float PI = 3.14159265;

float luminancia(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

/*
 * Onde este pixel está na retícula.
 *
 * `local` é a posição dentro da célula, de -0.5 a 0.5. `uvDoCentro` é onde a
 * imagem é lida para decidir o tamanho do ponto — o centro da célula, levado
 * de volta pelo giro da grade.
 *
 * Nas LINHAS não há célula no comprimento: a linha é contínua. Ela é lida no
 * centro só na espessura, e ao longo dela no próprio pixel — é o que faz a
 * linha engrossar e afinar suavemente acompanhando a imagem.
 */
struct Celula {
    vec2 local;
    vec2 uvDoCentro;
};

Celula celulaEm(vec2 uv, float anguloGraus, bool continuaNoComprimento) {
    // Células quadradas em qualquer proporção de composição: sem o acAspect,
    // um projeto 9:16 teria pontos ovais.
    float porAltura = acResolution.y / (max(dotSize, 1.0) * acEscalaDePixel);
    vec2 p = vec2(uv.x * acAspect, uv.y) * porAltura;

    float ang = radians(anguloGraus);
    float c = cos(ang);
    float s = sin(ang);
    vec2 r = vec2(p.x * c - p.y * s, p.x * s + p.y * c) + vec2(phase, 0.0);

    vec2 centro = floor(r) + 0.5;
    if (continuaNoComprimento) centro.x = r.x;

    vec2 rc = centro - vec2(phase, 0.0);
    // O giro inverso é a transposta: a matriz de rotação é ortogonal.
    vec2 pc = vec2(rc.x * c + rc.y * s, -rc.x * s + rc.y * c);

    Celula cel;
    cel.local = r - centro;
    cel.uvDoCentro = vec2(pc.x / porAltura / max(acAspect, 1e-4), pc.y / porAltura);
    return cel;
}

/*
 * Quanto da célula a forma cobre neste pixel, para uma quantidade de tinta.
 *
 * O limite de cada forma sai da ÁREA: `tinta` é a fração da célula que deve
 * ficar coberta. Um quadrado de lado 2L cobre 4L², então L = √tinta / 2. O
 * círculo cobre πr² até encostar nas bordas (78% da célula) e daí cresce até
 * fechar os cantos. O losango cobre 2L² até encostar, e depois perde só os
 * quatro triângulos dos cantos.
 */
float cobertura(vec2 local, float tinta, int forma, float borda) {
    float t = clamp(tinta, 0.0, 1.0);
    float metrica;
    float limite;

    if (forma == 1) {
        metrica = abs(local.y);
        limite = t * 0.5;
    } else if (forma == 2) {
        metrica = max(abs(local.x), abs(local.y));
        limite = sqrt(t) * 0.5;
    } else if (forma == 3) {
        metrica = abs(local.x) + abs(local.y);
        limite = t <= 0.5 ? sqrt(t * 0.5) : 1.0 - sqrt((1.0 - t) * 0.5);
    } else {
        metrica = length(local);
        float encosta = PI * 0.25;
        limite = t <= encosta
            ? sqrt(t / PI)
            : mix(0.5, 0.7072, (t - encosta) / (1.0 - encosta));
    }

    if (t <= 0.0) return 0.0;
    return 1.0 - smoothstep(limite - borda, limite + borda, metrica);
}

vec4 paraCmyk(vec3 cor) {
    float k = 1.0 - max(max(cor.r, cor.g), cor.b);
    float resto = max(1.0 - k, 1e-4);
    return vec4(
        (1.0 - cor.r - k) / resto,
        (1.0 - cor.g - k) / resto,
        (1.0 - cor.b - k) / resto,
        k
    );
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    bool linhas = shape == 1;

    // Um pixel, medido em células: a borda antisserrilhada tem essa largura.
    // A borda macia soma por cima, até meia célula.
    float borda = 0.75 / (max(dotSize, 1.0) * acEscalaDePixel) + softness * 0.5;

    vec3 sobrePapel;   // o resultado impresso no papel escolhido
    vec3 soTinta;      // a cor da tinta sozinha, para o papel transparente
    float quantaTinta; // quanto do pixel tem tinta, de 0 a 1

    if (colorMode == 2) {
        float base = gridAngle - 45.0;
        Celula cC = celulaEm(acScreenNorm, base + 15.0, linhas);
        Celula cM = celulaEm(acScreenNorm, base + 75.0, linhas);
        Celula cY = celulaEm(acScreenNorm, base + 0.0, linhas);
        Celula cK = celulaEm(acScreenNorm, base + 45.0, linhas);

        vec4 aC = texture(inputImg, cC.uvDoCentro);
        vec4 aM = texture(inputImg, cM.uvDoCentro);
        vec4 aY = texture(inputImg, cY.uvDoCentro);
        vec4 aK = texture(inputImg, cK.uvDoCentro);

        // Fora da camada não há tinta: o transparente guarda preto, e sem o
        // alfa aqui ele viraria retícula preta em volta do recorte.
        float covC = cobertura(cC.local, paraCmyk(aC.rgb).x * aC.a, shape, borda);
        float covM = cobertura(cM.local, paraCmyk(aM.rgb).y * aM.a, shape, borda);
        float covY = cobertura(cY.local, paraCmyk(aY.rgb).z * aY.a, shape, borda);
        float covK = cobertura(cK.local, paraCmyk(aK.rgb).w * aK.a, shape, borda);

        // Tinta sobre tinta MULTIPLICA: o ciano tira o vermelho da luz, o
        // magenta tira o verde, e onde os dois caem juntos sobra azul.
        vec3 filtro = mix(vec3(1.0), vec3(0.0, 1.0, 1.0), covC)
                    * mix(vec3(1.0), vec3(1.0, 0.0, 1.0), covM)
                    * mix(vec3(1.0), vec3(1.0, 1.0, 0.0), covY)
                    * mix(vec3(1.0), vec3(0.0), covK);

        sobrePapel = paperColor.rgb * filtro;
        quantaTinta = 1.0 - (1.0 - covC) * (1.0 - covM) * (1.0 - covY) * (1.0 - covK);
        // A cor que, pousada com esse alfa sobre branco, dá o mesmo filtro.
        soTinta = quantaTinta > 0.0
            ? (filtro - (1.0 - quantaTinta)) / quantaTinta
            : vec3(0.0);
    } else {
        Celula cel = celulaEm(acScreenNorm, gridAngle, linhas);
        vec4 lida = texture(inputImg, cel.uvDoCentro);

        float lumaPapel = luminancia(paperColor.rgb);
        vec3 corDaTinta = colorMode == 1 ? lida.rgb : inkColor.rgb;
        // Nas cores da imagem a tinta é "o contrário do papel": o ponto cresce
        // no escuro sobre papel claro, e no claro sobre papel escuro.
        float lumaTinta = colorMode == 1
            ? (lumaPapel > 0.5 ? 0.0 : 1.0)
            : luminancia(inkColor.rgb);

        float faixa = lumaTinta - lumaPapel;
        float tinta = abs(faixa) < 0.02
            ? 1.0 - luminancia(lida.rgb)
            : (luminancia(lida.rgb) - lumaPapel) / faixa;

        quantaTinta = cobertura(cel.local, tinta * lida.a, shape, borda);
        sobrePapel = mix(paperColor.rgb, corDaTinta, quantaTinta);
        soTinta = corDaTinta;
    }

    vec4 impresso = transparentPaper
        ? vec4(clamp(soTinta, 0.0, 1.0), quantaTinta * original.a)
        : vec4(sobrePapel, original.a);

    fragColor = impresso;
}
